input.command:
node -e "
const fs=require('fs');
const html=fs.readFileSync('index.html','utf8');
const external=/<(?:link|script|img|video|audio|source|iframe)[^>]+(?:href|src)=[\"'](?!data:)[^\"']+/gi;
const fonts=/@import|url\(['\"]?https?:/gi;
const matches=[...html.matchAll(external)].map(m=>m[0]);
const fontMatches=[...html.matchAll(fonts)].map(m=>m[0]);
console.log('external tags:', matches.length?matches:'none');
console.log('external css urls:', fontMatches.length?fontMatches:'none');
console.log('has reduced motion:', html.includes('prefers-reduced-motion'));
console.log('has pointermove:', html.includes('pointermove'));
console.log('inline style tag:', /<style>/.test(html));
console.log('inline script tag:', /<script>/.test(html));
console.log('size bytes:', Buffer.byteLength(html));
"

